import { NextResponse } from "next/server";
import { cookies } from "next/headers";

const COOKIE_NAME = "amsa_token";

/**
 * IMPORTANT:
 * Set this path to the exact Swagger endpoint for login.
 * Examples you might see in Swagger:
 *   /api/auth/login
 *   /api/Auth/Login
 *   /auth/login
 */
const BACKEND_LOGIN_PATH = "/api/login";

function extractToken(data: any): string | null {
    // Make it resilient to common naming conventions
    return (
        data?.token ??
        data?.access_token ??
        data?.accessToken ??
        data?.jwt ??
        data?.data?.token ??
        null
    );
}

export async function POST(req: Request) {
    const body = (await req.json()) as { username?: string; password?: string };

    const username = (body.username ?? "").trim();
    const password = body.password ?? "";

    if (username.length < 2 || password.length < 2) {
        return NextResponse.json(
            { ok: false, message: "Invalid credentials payload." },
            { status: 400 }
        );
    }

    const baseUrl = process.env.AMSA_API_BASE_URL;
    if (!baseUrl) {
        return NextResponse.json(
            { ok: false, message: "Missing AMSA_API_BASE_URL." },
            { status: 500 }
        );
    }

    // Call backend login
    const res = await fetch(`${baseUrl}${BACKEND_LOGIN_PATH}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        // Adjust keys if Swagger expects different names
        body: JSON.stringify({ username, password }),
        cache: "no-store",
    });

    // Pass through backend error text (helps debugging)
    if (!res.ok) {
        const text = await res.text();
        return NextResponse.json(
            { ok: false, message: text || "Login failed." },
            { status: res.status }
        );
    }

    const data = await res.json();

    const token = extractToken(data);
    if (!token) {
        return NextResponse.json(
            {
                ok: false,
                message:
                    "Login succeeded but token was not found. Update extractToken() to match Swagger response.",
            },
            { status: 500 }
        );
    }

    // Store token securely in httpOnly cookie
    const jar = await cookies();
    jar.set(COOKIE_NAME, token, {
        httpOnly: true,
        secure: true,
        sameSite: "lax",
        path: "/",
        // adjust based on swagger token expiration if available
        maxAge: 60 * 60 * 24 * 7, // 7 days
    });

    // Return minimal public info to the client (don’t return token)
    const user =
        data?.user ??
        data?.profile ??
        (typeof data?.username === "string" ? { username: data.username } : null) ??
        { username };

    return NextResponse.json({ ok: true, user });
}
